{
  "name": "safetwin5g-sandbox",
  "networks": {
    "core": {
      "name": "safetwin5g-isolated",
      "ipam": {
        "config": [
          {
            "subnet": "10.53.0.0/24"
          }
        ]
      },
      "internal": true
    }
  },
  "services": {
    "mongodb": {
      "command": [
        "mongod",
        "--bind_ip_all",
        "--quiet"
      ],
      "container_name": "safetwin5g-mongodb",
      "entrypoint": null,
      "healthcheck": {
        "test": [
          "CMD-SHELL",
          "mongosh --quiet --eval \"quit(db.adminCommand('ping').ok ? 0 : 2)\""
        ],
        "timeout": "3s",
        "interval": "3s",
        "retries": 30,
        "start_period": "10s"
      },
      "image": "docker.io/library/mongo:8.0.29-noble@sha256:021b2d5ae9d253f2cca17491cc8d03aed8df3c840f3252066aa62d3277fc406e",
      "networks": {
        "core": {
          "ipv4_address": "10.53.0.2"
        }
      },
      "restart": "no",
      "volumes": [
        {
          "type": "volume",
          "source": "mongodb_data",
          "target": "/data/db",
          "volume": {}
        },
        {
          "type": "bind",
          "source": "C:\\Users\\devel\\Documents\\Codex\\2026-08-22\\he\\safetwin-5g\\sandbox\\config\\mongodb\\10-subscriber.js",
          "target": "/docker-entrypoint-initdb.d/10-subscriber.js",
          "read_only": true,
          "bind": {}
        }
      ]
    },
    "open5gs": {
      "build": {
        "context": "C:\\Users\\devel\\Documents\\Codex\\2026-08-22\\he\\safetwin-5g\\sandbox\\docker\\open5gs",
        "dockerfile": "Dockerfile",
        "args": {
          "OPEN5GS_COMMIT": "318eeb49a7dcdff733dec60e02d9c60aefca2fb9",
          "OPEN5GS_TAG": "v2.7.7"
        }
      },
      "cap_add": [
        "NET_ADMIN",
        "NET_RAW"
      ],
      "command": null,
      "container_name": "safetwin5g-open5gs",
      "depends_on": {
        "mongodb": {
          "condition": "service_healthy",
          "required": true
        }
      },
      "devices": [
        {
          "source": "/dev/net/tun",
          "target": "/dev/net/tun",
          "permissions": "rwm"
        }
      ],
      "entrypoint": null,
      "healthcheck": {
        "test": [
          "CMD-SHELL",
          "curl --fail --silent http://10.53.0.3:9090/metrics \u003e/dev/null \u0026\u0026 pgrep -x open5gs-amfd \u003e/dev/null \u0026\u0026 pgrep -x open5gs-upfd \u003e/dev/null"
        ],
        "timeout": "4s",
        "interval": "5s",
        "retries": 36,
        "start_period": "15s"
      },
      "image": "safetwin5g/open5gs:2.7.7-318eeb49",
      "networks": {
        "core": {
          "ipv4_address": "10.53.0.3"
        }
      },
      "restart": "no",
      "sysctls": {
        "net.ipv4.ip_forward": "1"
      }
    },
    "prometheus": {
      "command": [
        "--config.file=/etc/prometheus/prometheus.yml",
        "--storage.tsdb.path=/prometheus",
        "--storage.tsdb.retention.time=7d",
        "--web.enable-lifecycle"
      ],
      "container_name": "safetwin5g-prometheus",
      "depends_on": {
        "open5gs": {
          "condition": "service_healthy",
          "required": true
        }
      },
      "entrypoint": null,
      "healthcheck": {
        "test": [
          "CMD",
          "/bin/promtool",
          "check",
          "healthy"
        ],
        "timeout": "3s",
        "interval": "5s",
        "retries": 24
      },
      "image": "docker.io/prom/prometheus:v3.13.2@sha256:508729e0e2d18e11fd742a5a5ca70e557b940a93948c3c95fd0123a6fd538b69",
      "networks": {
        "core": {
          "ipv4_address": "10.53.0.6"
        }
      },
      "restart": "no",
      "volumes": [
        {
          "type": "bind",
          "source": "C:\\Users\\devel\\Documents\\Codex\\2026-08-22\\he\\safetwin-5g\\sandbox\\config\\prometheus\\prometheus.yml",
          "target": "/etc/prometheus/prometheus.yml",
          "read_only": true,
          "bind": {}
        },
        {
          "type": "volume",
          "source": "prometheus_data",
          "target": "/prometheus",
          "volume": {}
        }
      ]
    },
    "ueransim-gnb": {
      "build": {
        "context": "C:\\Users\\devel\\Documents\\Codex\\2026-08-22\\he\\safetwin-5g\\sandbox\\docker\\ueransim",
        "dockerfile": "Dockerfile",
        "args": {
          "UERANSIM_COMMIT": "6bf5a1a96aaef6ae8778b9d8b477ac6e2bbf8156",
          "UERANSIM_TAG": "v3.3.0"
        }
      },
      "command": [
        "/opt/ueransim/bin/nr-gnb",
        "-c",
        "/etc/ueransim/gnb.yaml"
      ],
      "container_name": "safetwin5g-gnb",
      "depends_on": {
        "open5gs": {
          "condition": "service_healthy",
          "required": true
        }
      },
      "entrypoint": null,
      "healthcheck": {
        "test": [
          "CMD-SHELL",
          "pgrep -x nr-gnb \u003e/dev/null"
        ],
        "timeout": "3s",
        "interval": "5s",
        "retries": 24
      },
      "image": "safetwin5g/ueransim:3.3.0-6bf5a1a9",
      "networks": {
        "core": {
          "ipv4_address": "10.53.0.4"
        }
      },
      "restart": "no",
      "volumes": [
        {
          "type": "bind",
          "source": "C:\\Users\\devel\\Documents\\Codex\\2026-08-22\\he\\safetwin-5g\\sandbox\\config\\ueransim\\gnb.yaml",
          "target": "/etc/ueransim/gnb.yaml",
          "read_only": true,
          "bind": {}
        }
      ]
    },
    "ueransim-ue": {
      "cap_add": [
        "NET_ADMIN",
        "NET_RAW"
      ],
      "command": [
        "/opt/ueransim/bin/nr-ue",
        "-c",
        "/etc/ueransim/ue.yaml"
      ],
      "container_name": "safetwin5g-ue",
      "depends_on": {
        "ueransim-gnb": {
          "condition": "service_healthy",
          "required": true
        }
      },
      "devices": [
        {
          "source": "/dev/net/tun",
          "target": "/dev/net/tun",
          "permissions": "rwm"
        }
      ],
      "entrypoint": null,
      "healthcheck": {
        "test": [
          "CMD-SHELL",
          "ip link show uesimtun0 \u003e/dev/null 2\u003e\u00261"
        ],
        "timeout": "3s",
        "interval": "5s",
        "retries": 36,
        "start_period": "10s"
      },
      "image": "safetwin5g/ueransim:3.3.0-6bf5a1a9",
      "networks": {
        "core": {
          "ipv4_address": "10.53.0.5"
        }
      },
      "restart": "no",
      "volumes": [
        {
          "type": "bind",
          "source": "C:\\Users\\devel\\Documents\\Codex\\2026-08-22\\he\\safetwin-5g\\sandbox\\config\\ueransim\\ue.yaml",
          "target": "/etc/ueransim/ue.yaml",
          "read_only": true,
          "bind": {}
        }
      ]
    }
  },
  "volumes": {
    "mongodb_data": {
      "name": "safetwin5g-mongodb-data"
    },
    "prometheus_data": {
      "name": "safetwin5g-prometheus-data"
    }
  }
}

